"""Ordered, typed records and their textual representations."""
import math
import re
import json
import decimal
import copy

class Int(int):
    def __new__(cls, n, raw=None):
        obj = int.__new__(cls, n)
        obj.raw = raw
        return obj

class Float(float):
    def __new__(cls, n, raw=None):
        obj = float.__new__(cls, n)
        obj.raw = raw
        return obj

class Absent:
    def __bool__(self): return False
    def __repr__(self): return '(absent)'
    def __deepcopy__(self, memo): return self
ABS = Absent()

class Error:
    def __init__(self, message=''): self.message = message
    def __bool__(self): return False
    def __repr__(self): return '(error)'
ERR = Error()

class DataError(Exception):
    def __init__(self, text, code=1): self.text, self.code = text, code

class Record(dict):
    def __init__(self, data=(), ctx=None):
        super().__init__(data)
        self.ctx = ctx if ctx is not None else (0,0,'',0)
    def clone(self): return Record(copy.deepcopy(dict(self)), self.ctx)

class Text:
    def __init__(self, text, stderr=False): self.text,self.stderr = text,stderr

OFMT = None

def isnum(v): return isinstance(v,(int,float)) and not isinstance(v,bool)

def typename(v):
    if v is ABS: return 'absent'
    if isinstance(v,Error): return 'error'
    if v is None: return 'null'
    if isinstance(v,bool): return 'bool'
    if isinstance(v,int): return 'int'
    if isinstance(v,float): return 'float'
    if isinstance(v,str): return 'empty' if v == '' else 'string'
    if isinstance(v,dict): return 'map'
    if isinstance(v,list): return 'array'
    return 'func'

def isnull(v): return v is ABS or v is None or (isinstance(v,str) and v == '')

def infer(s, mode=None):
    if not isinstance(s,str): return s
    if mode == 'none' or not s or s != s.strip(): return s
    try:
        if re.fullmatch(r'[+-]?0[xX][0-9a-fA-F]+',s):
            n=int(s,16)
            return Float(n,s) if mode=='float' else Int(n,s)
        if re.fullmatch(r'[+-]?0[bB][01]+',s):
            n=int(s,2)
            return Float(n,s) if mode=='float' else Int(n,s)
        if re.fullmatch(r'[+-]?0[oO][0-7]+',s):
            n=int(s,8)
            return Float(n,s) if mode=='float' else Int(n,s)
        if re.fullmatch(r'[+-]?\d+',s):
            digits=s.lstrip('+-')
            if len(digits)>1 and digits[0]=='0':
                if mode!='octal': return s
                try: return Int(int(s,8),s)
                except ValueError: return Float(float(s),s)
            n=int(s)
            if mode=='float' or n < -(2**63) or n >= 2**63:
                return Float(float(s),s)
            return Int(n,s)
        if re.fullmatch(r'[+-]?(?:(?:\d+\.\d*|\.\d+)(?:[eE][+-]?\d+)?|\d+[eE][+-]?\d+)',s):
            return Float(float(s),s)
    except (ValueError,OverflowError): pass
    return s

def float_text(v):
    if math.isnan(v): return 'NaN'
    if math.isinf(v): return '+Inf' if v>0 else '-Inf'
    if v == 0: return '-0' if math.copysign(1,v)<0 else '0'
    s=repr(float(v))
    if 'e' in s or 'E' in s:
        s=format(decimal.Decimal(s),'f')
    if s.endswith('.0'): s=s[:-2]
    return s

def sprintf(fmt,v):
    fmt=re.sub(r'%(.*?)ll([diuoxX])',r'%\1\2',fmt)
    fmt=re.sub(r'%(.*?)l([fFeEgG])',r'%\1\2',fmt)
    try:
        if re.search(r'%[^%]*[xXodb]',fmt) and isnum(v): v=int(v)
        if re.search(r'%[^%]*b',fmt):
            return re.sub(r'%[^%]*b', format(int(v),'b'), fmt)
        if '%v' in fmt: return fmt.replace('%v',strval(v,False))
        return fmt % v
    except Exception: return '(error)'

def strval(v, usefmt=True):
    if v is ABS: return ''
    if isinstance(v,Error): return '(error)'
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v,float):
        if usefmt and OFMT: return sprintf(OFMT,v)
        raw=getattr(v,'raw',None)
        return raw if raw is not None else float_text(v)
    if isinstance(v,int):
        raw=getattr(v,'raw',None)
        return raw if raw is not None else str(v)
    if isinstance(v,str): return v
    if isinstance(v,(dict,list)): return json_text(v,True)
    return str(v)

def jquote(s):
    return json.dumps(str(s),ensure_ascii=False).replace('\u2028','\\u2028').replace('\u2029','\\u2029')

def json_text(v, stack=False, level=0, quoteall=False):
    if isinstance(v,dict):
        if not v: return '{}'
        if stack:
            return '{\n'+',\n'.join('  '*(level+1)+jquote(k)+': '+json_text(x,stack,level+1,quoteall) for k,x in v.items())+'\n'+'  '*level+'}'
        return '{'+', '.join(jquote(k)+': '+json_text(x,False,level+1,quoteall) for k,x in v.items())+'}'
    if isinstance(v,list):
        if not v: return '[]'
        if stack and any(isinstance(x,(dict,list)) and x for x in v):
            return '[\n'+',\n'.join('  '*(level+1)+json_text(x,stack,level+1,quoteall) for x in v)+'\n'+'  '*level+']'
        return '['+', '.join(json_text(x,False,level+1,quoteall) for x in v)+']'
    if quoteall: return jquote(strval(v))
    if isinstance(v,str): return jquote(v)
    if v is ABS: return 'null'
    if isinstance(v,Error): return '"(error)"'
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,int):
        raw=getattr(v,'raw',None)
        if raw is not None and re.fullmatch(r'-?(?:0|[1-9]\d*)',raw): return raw
        return str(int(v))
    return strval(v)

def json_load(s):
    return json.loads(s,parse_int=lambda s:Int(int(s),s),parse_float=lambda s:Float(float(s),s))

def freeze(v, strings=True):
    if isinstance(v,dict): return tuple((k,freeze(x,strings)) for k,x in v.items())
    if isinstance(v,list): return tuple(freeze(x,strings) for x in v)
    return strval(v) if strings else (typename(v),strval(v))

def sortkey(v):
    if isinstance(v,bool): return (1,int(v))
    if isnum(v): return (0, float(v))
    if isinstance(v,str) and v!='': return (2,v)
    if v is None: return (4,'')
    if isnull(v): return (5,'')
    if isinstance(v,Error): return (6,'')
    return (3,strval(v))

def flatten_map(m,sep='.',fields=None):
    out={}
    def go(prefix,v):
        if isinstance(v,dict) and v:
            for k,x in v.items(): go(prefix+sep+k,x)
        elif isinstance(v,list) and v:
            for i,x in enumerate(v): go(prefix+sep+str(i+1),x)
        else: out[prefix]=v
    for k,v in m.items():
        if fields is None or k in fields: go(k,v)
        else: out[k]=v
    return out

def arrayify(v):
    if isinstance(v,dict):
        d={k:arrayify(x) for k,x in v.items()}
        if len(d)>0 and list(d)==[str(i) for i in range(1,len(d)+1)]: return list(d.values())
        return d
    if isinstance(v,list): return [arrayify(x) for x in v]
    return v

def unflatten_map(m,sep='.',fields=None):
    out={}
    for k,v in m.items():
        parts=k.split(sep) if sep else [k]
        if fields is not None and parts[0] not in fields: parts=[k]
        node=out
        for p in parts[:-1]:
            if p not in node or not isinstance(node[p],dict): node[p]={}
            node=node[p]
        node[parts[-1]]=v
    return {k:arrayify(v) for k,v in out.items()}

def unique_keys(names):
    used=set(); result=[]
    for name in names:
        k=name; n=2
        while k in used:
            k=name+'_'+str(n); n+=1
        used.add(k); result.append(k)
    return result

def regex(s):
    flags=0
    if s.startswith('"') and s.endswith('"i'):
        s=s[1:-2]; flags=re.I
    elif s.startswith('"') and s.endswith('"'): s=s[1:-1]
    try: return re.compile(s,flags)
    except re.error: return re.compile(re.escape(s),flags)

def split_names(s): return s.split(',') if s else []
