"""Human-readable expression trees and static uninitialized-local warnings."""
import re
from values import *

class Node:
    def __init__(self,token,label,children=()):self.token,self.label,self.children=token,label,list(children)

def ast_tree(program):
    def node(n):
        tag=n[0]
        if tag=='lit':
            v=n[1];t=typename(v);text=strval(v)
            if isinstance(v,str):return Node(jquote(v),'string literal '+jquote(v))
            t='boolean' if t=='bool' else t
            return Node(text,t+' literal '+jquote(text))
        if tag in ('field','global','var'):
            token=('$' if tag=='field' else '@' if tag=='global' else '')+n[1]
            label=('direct field value' if tag=='field' else 'direct oosvar value' if tag=='global' else 'context variable' if n[1] in ('NR','FNR','NF','FILENAME','FILENUM','IPS','IFS','IRS','OPS','OFS','ORS','FLATSEP') else 'local variable')+' '+jquote(n[1])
            return Node(token,label)
        if tag=='full':return Node(n[1]+'*','full record' if n[1]=='$' else 'full oosvar')
        if tag=='index':return Node('[]','array or map index access "[]"',[node(n[1]),node(n[2])])
        if tag=='indirect':return Node('$[' if n[1]=='$' else '@[','indirect field value',[node(n[2])])
        if tag=='array':return Node('[]','array literal "[]"',[node(x) for x in n[1]])
        if tag=='map':return Node('{}','map literal "{}"',[Node(':','map-literal key-value pair ":"',[node(k),node(v)]) for k,v in n[1]])
        if tag in ('unary','binary'):return Node(n[1],'operator '+jquote(n[1]),[node(x) for x in n[2:]])
        if tag=='ternary':return Node('?:','operator "?:"',[node(x) for x in n[1:]])
        if tag=='assign':
            left=node(n[2]);right=node(n[3])
            if n[1]!='=':right=Node(n[1][:-1],'operator '+jquote(n[1][:-1]),[left,right])
            return Node('=','assignment "="',[left,right])
        if tag=='call':
            name=n[1][1] if n[1][0]=='var' else ''
            return Node(name,'function callsite'+(' '+jquote(name) if name else ''),[node(x) for x in n[2]])
        if tag=='expr':return node(n[1])
        if tag=='declare':return Node('=','assignment "="',[Node(n[2],'local variable '+jquote(n[2]),[Node(n[1],'type declaration '+jquote(n[1]))]),node(n[3])])
        if tag in ('begin','end'):return Node(tag,tag+' block',[block(n[1])])
        if tag=='if':
            kids=[]
            current=n;kw='if'
            while True:
                kids.append(Node(kw,'if-item '+jquote(kw),[node(current[1]),block(current[2])]))
                if len(current[3])==1 and current[3][0][0]=='if':current=current[3][0];kw='elif';continue
                if current[3]:kids.append(Node('else','if-item "else"',[block(current[3])]))
                break
            return Node('if-chain','if-chain',kids)
        if tag=='filter':return Node('filter','filter statement "filter"',[node(n[1])])
        if tag=='unset':return Node('unset','unset "unset"',[node(x) for x in n[1]])
        if tag=='output':
            word=n[1];children=[]
            if word in ('print','printn','eprint','eprintn'):
                children=[Node('','function callsite',[node(x) for x in n[2]]),Node('no-op','no-op')]
            elif word in ('emit','emitp','emitf'):
                args=n[2];entries=args[0][1] if args and args[0][0]=='tuple' else args[:1]
                children=[Node('[ERROR]','emittable list',[node(x) for x in entries]),Node('[ERROR]','emit keys',[node(x) for x in args[1:]]),Node('no-op','no-op')]
            else:children=[node(x) for x in n[2]]
            return Node(word,('print statement' if 'print' in word else 'emit statement' if 'emit' in word else word+' statement')+' '+jquote(word),children)
        if tag=='function':return Node('named-udf','function definition '+jquote(n[1]),[Node('parameters','parameter list',[Node('parameter','parameter',[Node(p,'parameter name '+jquote(p))]) for p in n[2]]),block(n[3])])
        if tag=='return':return Node('return','return "return"',[node(n[1])])
        if tag in ('break','continue'):return Node(tag,tag+' "'+tag+'"')
        if tag in ('while','do'):return Node(tag,tag,[node(n[1]),block(n[2])])
        return Node(tag,tag)
    def block(p):return Node('statement-block','statement block',[node(st) for st in p])
    return block(program)

def display(program,style):
    root=ast_tree(program)
    def compact(n):
        if not n.children:return n.token
        return '('+n.token+' '+ ' '.join(compact(c) for c in n.children)+')'
    def multiline(n,level):
        prefix='    '*level
        if not n.children or all(not c.children for c in n.children):return prefix+compact(n)+'\n'
        return prefix+'('+n.token+'\n'+''.join(multiline(c,level+1) for c in n.children)+prefix+')\n'
    def outline(n,level):return '    '*level+'* '+n.label+'\n'+''.join(outline(c,level+1) for c in n.children)
    if style=='D':return compact(root)+'\n\n'
    if style=='d':return multiline(root,0)+'\n'
    return 'AST:\n'+outline(root,0)+'\n'

